CREATE VIEW "public"."account_balances" WITH (security_invoker = true) AS (select "accounts"."id", "accounts"."user_id", "accounts"."name", "accounts"."type", "accounts"."currency", "accounts"."opening_balance", "accounts"."is_archived", "accounts"."created_at", "accounts"."updated_at", ("accounts"."opening_balance" + coalesce(sum("transactions"."amount"), 0))::bigint as "balance", count("transactions"."id")::int as "transaction_count" from "accounts" left join "transactions" on "transactions"."account_id" = "accounts"."id" group by "accounts"."id");